import{_ as s,a0 as n,w as r,s as l,ao as d,I as a,x as e,a1 as o,A as p}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const h=JSON.parse('{"title":"7-Zip 22.00 最终版现已推出 | LCTT x X-CMD","titleTemplate":false,"description":"7-Zip 22.00 最终版现已推出 | LCTT (202206) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"7-Zip 22.00 最终版现已推出 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"7-Zip 22.00 最终版现已推出 | LCTT (202206) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202206/20220621 The Final Version Of 7-Zip 22.00 Is Now Available","title":"7-Zip 22.00 最终版现已推出","tag":"202206","desc":""},"relativePath":"202206/20220621 The Final Version Of 7-Zip 22.00 Is Now Available.md","filePath":"[post].md"}'),m={name:"202206/20220621 The Final Version Of 7-Zip 22.00 Is Now Available.md"};function u(f,t,T,w,x,Z){const i=n("Link");return r(),l("div",null,[t[15]||(t[15]=d('<h1 id="_7-zip-22-00-最终版现已推出" tabindex="-1">7-Zip 22.00 最终版现已推出 <a class="header-anchor" href="#_7-zip-22-00-最终版现已推出" aria-label="Permalink to “7-Zip 22.00 最终版现已推出”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202206/27/110310hwrmxuwyqlor1olp.jpg" alt=""></p><p>7-Zip 是用于 Windows、Mac 和 Linux 的知名开源文件归档器。它的最新版本 22.00 现已推出。它是 2022 年的第一个稳定版本。上一个版本是 21.07，于 2021 年 12 月发布。7-Zip 的用户可以从官方网站获取该应用的最新版本，下载适用于 Windows 64 位、32 位和 ARM 版本。该应用仍然与过时的 Windows 版本兼容，例如 XP 和 Vista。它还支持所有官方支持的 Windows 版本，包括服务器版本。适用于 Linux 的 7-Zip 22.00 已经可以下载，但 Mac OS 版本还不可用。</p><p>7-Zip 22.00 包含一些增强了应用功能的新特性。这个归档器现在支持提取<ruby>苹果文件系统<rt>Apple File System</rt></ruby>（APFS）镜像。几年前，苹果公司在 Mac OS 10.13 和 iOS 中引入了苹果文件系统。该文件系统在设计时就考虑到了闪存（Flash）和固态硬盘（SSD）存储。</p><p>7-Zip 22.00 包括了对其 TAR 存档支持的多项增强。使用选项 <code>-ttar -mm=pax</code> 或 <code>-ttar -mm=posix</code>，7-Zip 现在可以创建符合 POSIX 标准的 tar 格式的 TAR 档案。此外，使用选项 <code>ttar -mm=pax -mtp=3 -mtc -mta</code>，7-Zip 可以在 tar/pax 存档中存储高精度的文件时间戳。</p><p>最后，Linux 用户可以在 TAR 归档文件中使用以下两个新选项：</p><ul><li><code>snoi</code>：将所有者/组 ID 保存在存档中，或将所有者/组 ID 从存档复制到提取的文件中。</li><li><code>snon</code>：在存档中保留所有者/组的名称。</li></ul><p>适用于 Windows 的 7-Zip 22.00 添加了对 <code>-snz</code> 选项的支持，该选项用于传播区识别符（LCTT 译注：区标识符是微软在 2013 年为 IE 设计的安全功能，它会标记那些用户自网络上所下载的文件，并在用户准备打开时跳出警告）。</p><p>要提取文件，请使用标识符流。出于安全目的，Windows 使用了该流，它可用于确定文件是在本地创建的还是从互联网下载的。</p><p>在“<ruby>添加到存档<rt>add to archive</rt></ruby>”配置对话框中，7-Zip 22.00 包含一个新的选项窗口。它包括用于更改时间戳精度、更改其他与时间相关的配置选项，以及防止更改源文件的最后访问时间等选项。</p><hr>',11)),a("p",null,[t[1]||(t[1]=e("via: ",-1)),o(i,{href:"https://www.opensourceforu.com/2022/06/the-final-version-of-7-zip-22-00-is-now-available/"},{default:p(()=>[...t[0]||(t[0]=[e("https://www.opensourceforu.com/2022/06/the-final-version-of-7-zip-22-00-is-now-available/",-1)])]),_:1})]),a("p",null,[t[6]||(t[6]=e("作者：",-1)),o(i,{href:"https://www.opensourceforu.com/author/laveesh-kocher/"},{default:p(()=>[...t[2]||(t[2]=[e("Laveesh Kocher",-1)])]),_:1}),t[7]||(t[7]=e(" 选题：",-1)),o(i,{href:"https://github.com/lkxed"},{default:p(()=>[...t[3]||(t[3]=[e("lkxed",-1)])]),_:1}),t[8]||(t[8]=e(" 译者：",-1)),o(i,{href:"https://github.com/lkxed"},{default:p(()=>[...t[4]||(t[4]=[e("lkxed",-1)])]),_:1}),t[9]||(t[9]=e(" 校对：",-1)),o(i,{href:"https://github.com/wxy"},{default:p(()=>[...t[5]||(t[5]=[e("wxy",-1)])]),_:1})]),a("p",null,[t[12]||(t[12]=e("本文由 ",-1)),o(i,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...t[10]||(t[10]=[e("LCTT",-1)])]),_:1}),t[13]||(t[13]=e(" 原创编译，",-1)),o(i,{href:"https://linux.cn/"},{default:p(()=>[...t[11]||(t[11]=[e("Linux中国",-1)])]),_:1}),t[14]||(t[14]=e(" 荣誉推出",-1))])])}const v=s(m,[["render",u]]);export{h as __pageData,v as default};
